using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResource
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["version"] = "1.0.0",
        ["environment"] = "production",
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false
        },
        ["maxRetries"] = 3,
        ["timeoutSeconds"] = 30
    };

    [McpServerResource(UriTemplate = "config://app", Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON")]
    public static string GetAppConfig()
    {
        return JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Gets the value of a specific configuration key")]
    public static string GetConfigValue(
        [Description("The configuration key to look up (e.g., 'version', 'environment', 'maxRetries')")] string key)
    {
        var config = new Dictionary<string, string>
        {
            ["version"] = "1.0.0",
            ["environment"] = "production",
            ["maxRetries"] = "3",
            ["timeoutSeconds"] = "30"
        };

        return config.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Unknown configuration key: {key}";
    }

    [McpServerTool, Description("Lists all available configuration keys")]
    public static string ListConfigKeys()
    {
        return string.Join(", ", "version", "environment", "features", "maxRetries", "timeoutSeconds");
    }
}

